/**
 * 「从文件名按表达式提取标签」的默认规则。
 *
 * 单独成文件是为了避开 UploadService ↔ SysConfigService 的循环引用：
 * 前者要读配置，后者要在升级老数据时把历史默认值改写成新默认值，
 * 两边都要拿到同一份默认值。
 *
 * v1.0.6：起止符改为**纯符号串**存储（每个字符就是一个记号），
 * 与设置页输入框里看到的形态完全一致。
 *   · 起始：`#@&`
 *   · 截断：`#@&!！,，.。-—_、;；:：?？~$()（）[]【】{}<>《》|/\`
 *     （起始符重复出现是刻意的：`#美食#风景` 要在前一个 `#` 处断开）
 *   · 空格恒为截断符，由 extractByMarkers 写死，不进配置
 *   · 限长 10 位，超长整条丢弃（不截短）
 */
export const DEFAULT_TAG_START = '#@&';

export const DEFAULT_TAG_STOP = '#@&!！,，.。-—_\u3001;；:：?？~$()（）[]【】{}<>《》|/\\';

export const DEFAULT_TAG_MAX_LEN = 10;
